// generated by tools/build_verse_manifests.js from jst_english.js — Dual-view English for the chapters of jst_verses/jstluke.js
registerEnglish([["Luke",1,1,"And while he executed the priest’s office before God, in the order of his priesthood,"],["Luke",2,1,"And it came to pass, after three days they found him in the temple, sitting in the midst of the doctors, and they were hearing him, and asking him questions."],["Luke",3,1,"As it is written in the book of the prophet Esaias; and these are the words, saying, The voice of one crying in the wilderness, Prepare ye the way of the Lord, and make his paths straight."],["Luke",3,2,"For behold, and lo, he shall come, as it is written in the book of the prophets, to take away the sins of the world, and to bring salvation unto the heathen nations, to gather together those who are lost, who are of the sheepfold of Israel;"],["Luke",3,3,"Yea, even the dispersed and afflicted; and also to prepare the way, and make possible the preaching of the gospel unto the Gentiles;"],["Luke",3,4,"And to be a light unto all who sit in darkness, unto the uttermost parts of the earth; to bring to pass the resurrection from the dead, and to ascend up on high, to dwell on the right hand of the Father,"],["Luke",3,5,"Until the fullness of time, and the law and the testimony shall be sealed, and the keys of the kingdom shall be delivered up again unto the Father;"],["Luke",3,6,"To administer justice unto all; to come down in judgment upon all, and to convince all the ungodly of their ungodly deeds, which they have committed; and all this in the day that he shall come;"],["Luke",3,7,"For it is a day of power; yea, every valley shall be filled, and every mountain and hill shall be brought low; the crooked shall be made straight, and the rough ways made smooth;"],["Luke",3,8,"And all flesh shall see the salvation of God."],["Luke",4,1,"And unto him who smiteth thee on the cheek, offer also the other; or, in other words, it is better to offer the other, than to revile again. And him who taketh away thy cloak, forbid not to take thy coat also."],["Luke",4,2,"For it is better that thou suffer thine enemy to take these things, than to contend with him. Verily I say unto you, Your heavenly Father who seeth in secret, shall bring that wicked one into judgment."],["Luke",5,1,"For whosoever will save his life, must be willing to lose it for my sake; and whosoever will be willing to lose his life for my sake, the same shall save it."],["Luke",5,2,"For what doth it profit a man if he gain the whole world, and yet he receive him not whom God hath ordained, and he lose his own soul, and he himself be a castaway?"],["Luke",6,1,"Woe unto you, lawyers! For ye have taken away the key of knowledge, the fullness of the scriptures; ye enter not in yourselves into the kingdom; and those who were entering in, ye hindered."],["Luke",7,1,"But he who denieth me before men, shall be denied before the angels of God."],["Luke",7,2,"Now his disciples knew that he said this, because they had spoken evil against him before the people; for they were afraid to confess him before men."],["Luke",7,3,"And they reasoned among themselves, saying, He knoweth our hearts, and he speaketh to our condemnation, and we shall not be forgiven. But he answered them, and said unto them,"],["Luke",7,4,"Whosoever shall speak a word against the Son of man, and repenteth, it shall be forgiven him; but unto him who blasphemeth against the Holy Ghost, it shall not be forgiven him."],["Luke",7,5,"For, behold, he cometh in the first watch of the night, and he shall also come in the second watch, and again he shall come in the third watch."],["Luke",8,1,"Then certain of them came to him, saying, Good Master, we have Moses and the prophets, and whosoever shall live by them, shall he not have life?"],["Luke",8,2,"And Jesus answered, saying, Ye know not Moses, neither the prophets; for if ye had known them, ye would have believed on me; for to this intent they were written. For I am sent that ye might have life. Therefore I will liken it unto salt which is good;"],["Luke",8,3,"But if the salt has lost its savor, wherewith shall it be seasoned?"],["Luke",9,1,"And they said unto him, We have the law, and the prophets; but as for this man we will not receive him to be our ruler; for he maketh himself to be a judge over us."],["Luke",9,2,"Then said Jesus unto them, The law and the prophets testify of me; yea, and all the prophets who have written, even until John, have foretold of these days."],["Luke",9,3,"Since that time, the kingdom of God is preached, and every man who seeketh truth presseth into it."],["Luke",9,4,"And it is easier for heaven and earth to pass, than for one tittle of the law to fail."],["Luke",9,5,"And why teach ye the law, and deny that which is written; and condemn him whom the Father hath sent to fulfill the law, that ye might all be redeemed?"],["Luke",9,6,"O fools! for you have said in your hearts, There is no God. And you pervert the right way; and the kingdom of heaven suffereth violence of you; and you persecute the meek; and in your violence you seek to destroy the kingdom; and ye take the children of the kingdom by force. Woe unto you, ye adulterers!"],["Luke",10,1,"Neither shall they say, Lo, here! or, Lo, there! For, behold, the kingdom of God has already come unto you."],["Luke",10,2,"And they answered and said unto him, Where, Lord, shall they be taken?"],["Luke",10,3,"And he said unto them, Wheresoever the body is gathered; or, in other words, whithersoever the saints are gathered, thither will the eagles be gathered together; or, thither will the remainder be gathered together."],["Luke",10,4,"This he spake, signifying the gathering of his saints; and of angels descending and gathering the remainder unto them; the one from the bed, the other from the grinding, and the other from the field, whithersoever he listeth."],["Luke",10,5,"For verily there shall be new heavens, and a new earth, wherein dwelleth righteousness."],["Luke",10,6,"And there shall be no unclean thing; for the earth becoming old, even as a garment, having waxed in corruption, wherefore it vanisheth away, and the footstool remaineth sanctified, cleansed from all sin."],["Luke",11,1,"And he said unto them, It is impossible for them who trust in riches, to enter into the kingdom of God; but he who forsaketh the things which are of this world, it is possible with God, that he should enter in."],["Luke",12,1,"Now these things he spake unto them, concerning the destruction of Jerusalem. And then his disciples asked him, saying, Master, tell us concerning thy coming?"],["Luke",12,2,"And he answered them, and said, In the generation in which the times of the Gentiles shall be fulfilled, there shall be signs in the sun, and in the moon, and in the stars; and upon the earth distress of nations with perplexity, like the sea and the waves roaring. The earth also shall be troubled, and the waters of the great deep;"],["Luke",12,3,"Men’s hearts failing them for fear, and for looking after those things which are coming on the earth. For the powers of heaven shall be shaken."],["Luke",12,4,"Verily I say unto you, this generation, the generation when the times of the Gentiles be fulfilled, shall not pass away till all be fulfilled."],["Luke",13,1,"Then said Jesus, Father, forgive them; for they know not what they do (Meaning the soldiers who crucified him,) and they parted his raiment and cast lots."],["Luke",14,1,"And they found the stone rolled away from the sepulcher, and two angels standing by it in shining garments."],["Luke",14,2,"And they entered into the sepulcher, and not finding the body of the Lord Jesus, they were much perplexed thereabout;"],["Luke",14,3,"And were affrighted, and bowed down their faces to the earth. But behold the angels said unto them, Why seek ye the living among the dead?"]]);
